const root=document.querySelector('#app');
const siteLanguages={ar:'العربية',en:'English','zh-Hant':'繁體中文','zh-Hans':'简体中文',es:'Español',ja:'日本語',vi:'Tiếng Việt',th:'ไทย',id:'Bahasa Indonesia',fr:'Français',de:'Deutsch',it:'Italiano',nl:'Nederlands',ko:'한국어',ru:'Русский',tr:'Türkçe',my:'မြန်မာဘာသာ',pt:'Português'};
const closeLanguageLabels={ar:'إغلاق',en:'Close','zh-Hant':'關閉','zh-Hans':'关闭',es:'Cerrar',ja:'閉じる',vi:'Đóng',th:'ปิด',id:'Tutup',fr:'Fermer',de:'Schließen',it:'Chiudi',nl:'Sluiten',ko:'닫기',ru:'Закрыть',tr:'Kapat',my:'ပိတ်ရန်',pt:'Fechar'};
const settingsLabels={en:['Settings','Always show translation'],ar:['الإعدادات','إظهار الترجمة دائمًا'],'zh-Hant':['設定','一律顯示翻譯'],'zh-Hans':['设置','始终显示翻译'],es:['Configuración','Mostrar siempre la traducción'],ja:['設定','翻訳を常に表示'],vi:['Cài đặt','Luôn hiển thị bản dịch'],th:['การตั้งค่า','แสดงคำแปลเสมอ'],id:['Pengaturan','Selalu tampilkan terjemahan'],fr:['Paramètres','Toujours afficher la traduction'],de:['Einstellungen','Übersetzung immer anzeigen'],it:['Impostazioni','Mostra sempre la traduzione'],nl:['Instellingen','Vertaling altijd tonen'],ko:['설정','번역 항상 표시'],ru:['Настройки','Всегда показывать перевод'],tr:['Ayarlar','Çeviriyi her zaman göster'],my:['ဆက်တင်များ','ဘာသာပြန်ကို အမြဲပြပါ'],pt:['Configurações','Sempre mostrar tradução']};
const translationUnavailable={en:'Translation is not available for this level yet.',ar:'الترجمة غير متاحة لهذا المستوى بعد.','zh-Hant':'此程度的翻譯尚未提供。','zh-Hans':'此级别的翻译尚未提供。',es:'La traducción para este nivel aún no está disponible.',ja:'このレベルの翻訳はまだありません。',vi:'Bản dịch cho cấp độ này chưa có.',th:'ยังไม่มีคำแปลสำหรับระดับนี้',id:'Terjemahan untuk level ini belum tersedia.',fr:'La traduction pour ce niveau n’est pas encore disponible.',de:'Für dieses Niveau ist noch keine Übersetzung verfügbar.',it:'La traduzione per questo livello non è ancora disponibile.',nl:'Voor dit niveau is nog geen vertaling beschikbaar.',ko:'이 레벨의 번역은 아직 제공되지 않습니다.',ru:'Перевод для этого уровня пока недоступен.',tr:'Bu seviye için henüz çeviri yok.',my:'ဤအဆင့်အတွက် ဘာသာပြန် မရရှိနိုင်သေးပါ။',pt:'A tradução para este nível ainda não está disponível.'};
let interfaceLanguage=localStorage.getItem('site-language')||'en';
if(interfaceLanguage==='zh')interfaceLanguage='zh-Hant';
let theme=localStorage.getItem('site-theme')||'light';
document.documentElement.dataset.theme=theme;
let alwaysShowTranslation=localStorage.getItem('reader-always-show-translation')!=='false';
let catalog={genres:[],stories:[]}, currentStory=null, matchedStoryIds=null, searchSequence=0, showTranslation=alwaysShowTranslation, roman=false, searchLanguage=new URLSearchParams(location.search).get('searchBy')==='source'?'source':'target';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nativeLanguageNames={...siteLanguages,'en-US':'English (US)','en-GB':'English (UK)','en-AU':'English (Australia)','es-MX':'Español (México)','es-ES':'Español (España)'};
function sortedLanguageItems(codes){return codes.map(code=>({code,name:nativeLanguageNames[code]||code})).sort((a,b)=>a.name.localeCompare(b.name,'en'));}
function languageOptions(codes,selected){return sortedLanguageItems(codes).map(({code,name})=>`<option value="${escape(code)}" lang="${escape(code)}" dir="auto" ${selected===code?'selected':''}>${escape(name)}</option>`).join('');}
async function api(url,options){const r=await fetch('/api/reader'+url,options);const d=await r.json();if(!r.ok)throw Error(d.error||'Something went wrong.');return d}
function settingsMenu(){const [title,label]=settingsLabels[interfaceLanguage]||settingsLabels.en;return `<a href="#reader-settings" id="reader-settings-trigger" class="settings-trigger" data-action="open-settings" aria-label="${escape(title)}" title="${escape(title)}" aria-haspopup="dialog" aria-controls="reader-settings"><svg viewBox="0 0 24 24" aria-hidden="true"><use href="/assets/icons/lucide-sprite.svg#settings"></use></svg><span class="settings-link-label">${escape(title)}</span></a><dialog id="reader-settings" class="app-modal settings-modal" aria-labelledby="reader-settings-title"><div class="modal-header"><h2 id="reader-settings-title">${escape(title)}</h2><button type="button" class="modal-close" data-action="close-settings" aria-label="${escape(closeLanguageLabels[interfaceLanguage]||closeLanguageLabels.en)}">&times;</button></div><label class="settings-option"><input id="always-show-translation" type="checkbox" ${alwaysShowTranslation?'checked':''}><span>${escape(label)}</span></label></dialog>`;}
function siteLanguageLink(){const label=translations[interfaceLanguage]?.['Site language']||'Site language';const name=siteLanguages[interfaceLanguage]||siteLanguages.en;return `<a href="#site-language" id="site-language-link" class="site-language-link" data-action="open-language" aria-haspopup="dialog" aria-controls="site-language" aria-label="${escape(label)}: ${escape(name)}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"></path></svg><span class="site-language-name" lang="${escape(interfaceLanguage)}" dir="auto">${escape(name)}</span></a><dialog id="site-language" class="app-modal language-modal" aria-labelledby="site-language-title"><div class="modal-header"><h2 id="site-language-title">${escape(label)}</h2><button type="button" class="modal-close" data-action="close-language" aria-label="${escape(closeLanguageLabels[interfaceLanguage]||closeLanguageLabels.en)}">&times;</button></div><div class="language-list">${sortedLanguageItems(Object.keys(siteLanguages)).map(({code,name})=>`<button type="button" data-site-language="${escape(code)}" lang="${escape(code)}" dir="auto" aria-pressed="${interfaceLanguage===code}"><span>${escape(name)}</span>${interfaceLanguage===code?'<span aria-hidden="true">✓</span>':''}</button>`).join('')}</div></dialog>`;}
function header(){const query=new URLSearchParams(location.search).get('q')||'';const storyDetail=location.pathname.startsWith('/story/');const storyPages=storyDetail||location.pathname==='/library'||location.pathname.startsWith('/library/genre/');return `<header class="header"><a href="/" class="brand"><img src="/assets/img/linguastories.png" alt=""><span>LinguaStories</span></a><nav aria-label="Main navigation">${storyDetail||['/','/library'].includes(location.pathname)?'':'<a href="/library">Explore stories</a>'}${siteLanguageLink()}${storyPages?settingsMenu():''}<button class="theme-toggle" data-action="theme" type="button" aria-label="${theme==='dark'?'Switch to light mode':'Switch to dark mode'}" title="${theme==='dark'?'Light mode':'Dark mode'}">${theme==='dark'?'&#9728;':'&#9790;'}</button>${storyDetail||location.pathname==='/'?'':`<form class="header-search${query?' expanded':''}" action="/library" role="search"><button type="button" data-action="search" aria-label="Open story search" aria-expanded="${!!query}" aria-controls="story-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="7"></circle><path d="m16 16 4 4"></path></svg></button><input id="story-search" name="q" type="search" aria-label="Search stories" placeholder="Search stories" value="${escape(query)}" autocomplete="off" ${query?'':'hidden'}></form>`}</nav></header>`}

function footer(){return `<footer><a class="brand" href="/"><img src="/assets/img/linguastories.png" alt=""><span>LinguaStories</span></a><p>Good stories. A little reading every day.</p><a href="/library">Explore the library →</a></footer>`}
function siteMatchesTarget(target){try{const site=new Intl.Locale(interfaceLanguage),story=new Intl.Locale(target);return site.language===story.language && (!site.script||!story.script||site.script===story.script);}catch{return interfaceLanguage===target;}}
const cardNotice={en:'This story is in {language}.',ar:'هذه القصة باللغة {language}.','zh-Hant':'這個故事的語言是{language}。','zh-Hans':'这个故事的语言是{language}。',es:'Esta historia está en {language}.',ja:'この物語の言語：{language}。',vi:'Câu chuyện này bằng {language}.',th:'เรื่องนี้เป็นภาษา{language}',id:'Cerita ini dalam bahasa {language}.',fr:'Cette histoire est en {language}.',de:'Diese Geschichte ist auf {language}.',it:'Questa storia è in {language}.',nl:'Dit verhaal is in het {language}.',ko:'이 이야기는 {language}로 쓰여 있습니다.',ru:'Язык этой истории: {language}.',tr:'Bu hikâye {language} dilindedir.',my:'ဤဇာတ်လမ်း၏ ဘာသာစကားမှာ {language} ဖြစ်သည်။',pt:'Esta história está em {language}.'};
function card(s,i=0,homepage=false,showGenre=true){const chosenLevel=new URLSearchParams(location.search).get('level');const cardLevel=s.levels?.find(v=>v.level===chosenLevel)?.level||s.level;const message=(cardNotice[interfaceLanguage]||cardNotice.en).replace('{language}',languageName(s.targetLanguage));const notice=siteMatchesTarget(s.targetLanguage)?'':`<span class="card-language-notice">${escape(message)}</span>`;return `<a class="card" href="/story/${s.id}${filterQuery()}" aria-label="Read ${escape(s.title)}"><div class="card-art art-${i%5}"><img src="${escape(s.image)}" alt="" loading="lazy">${showGenre?`<span class="card-badge">${escape(genreLabel(s.genre))}</span>`:''}</div><div class="card-body"><span class="eyebrow">${homepage?escape(cardLevel):`${escape(languageName(s.targetLanguage)).toUpperCase()} · ${escape(cardLevel)}`}</span><h3 lang="${escape(s.targetLanguage)}" dir="auto">${escape(s.title)}</h3><p class="card-description" lang="${escape(s.targetLanguage)}" dir="auto">${escape(s.description)}</p>${homepage?'':notice}</div></a>`;}

function home(){let featured=catalog.stories.filter((s,i)=>i%10===0).slice(0,4);return `${header()}<main><section class="hero wrap"><div class="hero-copy"><span class="eyebrow"><span class="dot"></span> A LITTLE READING, EVERY DAY</span><h1>Find your next<br><em>favorite story.</em></h1><p>Make language learning part of your day with stories you’ll enjoy reading. Start anywhere, take your time, and see how far a little reading can take you.</p><div class="actions"><a class="button primary" href="/library">Explore stories <span>→</span></a><a class="button subtle" href="#how">How it works</a></div><div class="hero-note"><span>✦</span> From A1 to C2, grow your reading confidence.</div></div><div class="hero-art"><img src="/assets/img/story-town.png" alt="A friendly cartoon town with people reading and meeting in a park"><div class="art-label"><span>✦</span><div><strong>A world of stories</strong><small>One page at a time</small></div></div></div></section><section class="intro wrap" id="how"><div><span class="eyebrow">A MORE ENJOYABLE WAY TO LEARN</span><h2>Stories make the words<br>stick with you.</h2></div><p>Meet new words in moments that make sense. Explore stories at your level and come back whenever you like.</p></section><section class="features wrap"><div><span>01</span><h3>Pick a story</h3><p>From little everyday moments to new adventures, there’s something for every mood.</p></div><div><span>02</span><h3>Read at your pace</h3><p>From your first words at A1 to confident reading at C2, take each story at your own pace.</p></div><div><span>03</span><h3>Keep coming back</h3><p>A few minutes with a good story can make reading feel like a habit you enjoy.</p></div></section><section class="home-stories wrap"><div class="section-heading"><div><span class="eyebrow">SOMETHING FOR EVERY MOOD</span><h2>What will you read today?</h2><p>A few places to begin.</p></div><a class="inline-link" href="/library">See all stories →</a></div><div class="home-grid">${featured.map((s,i)=>card(s,i,true)).join('')}</div></section><section class="cta wrap"><div><span class="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2>There’s a story waiting for you.</h2><p>No account needed to start reading.</p><a href="/library" class="button primary">Read a story →</a></div></section></main>${footer()}`}
const languages={ar:'Arabic',en:'English (US)','en-GB':'English (UK)','en-AU':'English (Australian)','zh-Hant':'Mandarin (Traditional)','zh-Hans':'Mandarin (Simplified)','es-MX':'Spanish (Mexico)','es-ES':'Spanish (Spain)',ja:'Japanese',vi:'Vietnamese',th:'Thai',id:'Indonesian',fr:'French',de:'German',it:'Italian',nl:'Dutch',ko:'Korean',ru:'Russian',tr:'Türkiye',my:'Burmese',pt:'Portuguese'};
function languageName(code){if(!code)return '';if(interfaceLanguage==='en')return languages[code]||siteLanguages[code]||code;try{return new Intl.DisplayNames([interfaceLanguage],{type:'language'}).of(code)||languages[code]||code}catch{return languages[code]||code}}
const genreSlug=g=>g.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function selection(){const q=new URLSearchParams(location.search);return {target:languages[q.get('target')]?q.get('target'):'en',source:languages[q.get('source')]?q.get('source'):'zh-Hant'};}
function filteredStories(){const {target,source}=selection();const q=new URLSearchParams(location.search),level=q.get('level'),audio=q.get('audio')==='1';return catalog.stories.filter(s=>{const versions=s.levels||[{level:s.level,availableLanguages:s.sourceLanguages.map(language=>({language}))}];return versions.some(v=>(!level||v.level===level)&&(searchLanguage==='target'?s.targetLanguage===target:v.availableLanguages.some(item=>item.language===source)))&&(!audio||!!s.audio);});}
function filters(){const {target,source}=selection();const options=languageOptions(Object.keys(languages),searchLanguage==='target'?target:source);return `<div class="preference"><span class="preference-label">Preference</span><div class="preference-controls"><label><span class="visually-hidden">Preference type</span><select id="preference-type"><option value="target" ${searchLanguage==='target'?'selected':''}>Target Language</option><option value="source" ${searchLanguage==='source'?'selected':''}>Source Language</option></select></label><label><span class="visually-hidden">Language</span><select id="preference-language">${options}</select></label></div><div class="extra-filters"><label>Level <select id="level-filter"><option value="">All levels</option>${['A1','A2','B1','B2','C1','C2'].map(level=>`<option value="${level}" ${new URLSearchParams(location.search).get('level')===level?'selected':''}>${level}</option>`).join('')}</select></label><label class="audio-filter"><input id="audio-filter" type="checkbox" ${new URLSearchParams(location.search).get('audio')==='1'?'checked':''}> Has audio</label></div></div>`;}
function filterQuery(){const query=new URLSearchParams(selection()),current=new URLSearchParams(location.search);for(const key of ['level','audio','searchBy'])if(current.get(key))query.set(key,current.get(key));return '?'+query.toString();}
const nextStoryLabels={en:'Read next story →',ar:'اقرأ القصة التالية ←','zh-Hant':'閱讀下一個故事 →','zh-Hans':'阅读下一个故事 →',es:'Leer la siguiente historia →',ja:'次の物語を読む →',vi:'Đọc truyện tiếp theo →',th:'อ่านเรื่องถัดไป →',id:'Baca cerita berikutnya →',fr:'Lire l’histoire suivante →',de:'Nächste Geschichte lesen →',it:'Leggi la prossima storia →',nl:'Lees het volgende verhaal →',ko:'다음 이야기 읽기 →',ru:'Читать следующую историю →',tr:'Sonraki hikâyeyi oku →',my:'နောက်ဇာတ်လမ်းကို ဖတ်ရန် →',pt:'Ler a próxima história →'};
const nextChapterLabels={en:'Ready for the next chapter?',ar:'هل أنت مستعد للفصل التالي؟','zh-Hant':'準備好閱讀下一章了嗎？','zh-Hans':'准备好阅读下一章了吗？',es:'¿Listo para el siguiente capítulo?',ja:'次の章を読む準備はできましたか？',vi:'Bạn đã sẵn sàng cho chương tiếp theo chưa?',th:'พร้อมสำหรับบทต่อไปหรือยัง?',id:'Siap untuk bab berikutnya?',fr:'Prêt pour le prochain chapitre ?',de:'Bereit für das nächste Kapitel?',it:'Pronto per il prossimo capitolo?',nl:'Klaar voor het volgende hoofdstuk?',ko:'다음 장을 읽을 준비가 되셨나요?',ru:'Готовы к следующей главе?',tr:'Sonraki bölüme hazır mısın?',my:'နောက်အခန်းကို ဖတ်ဖို့ အဆင်သင့်ဖြစ်ပြီလား။',pt:'Pronto para o próximo capítulo?'};
function nextStoryInSeries(story){if(!story.seriesId||!Number.isFinite(story.seriesOrder))return null;return catalog.stories.filter(item=>item.seriesId===story.seriesId&&Number.isFinite(item.seriesOrder)&&item.seriesOrder>story.seriesOrder).sort((a,b)=>a.seriesOrder-b.seriesOrder)[0]||null;}
function nextStoryUrl(next){const query=new URLSearchParams(filterQuery().slice(1));const level=query.get('level');if(level&&!next.levels?.some(item=>item.level===level||item.storyLevelId===level))query.delete('level');return `/story/${encodeURIComponent(next.id)}?${query.toString()}`;}
function genreUrl(g){return `/library/genre/${genreSlug(g)}${filterQuery()}`;}
function libraryResults(query=''){const term=query.trim().toLocaleLowerCase();const selected=selection();if(term && matchedStoryIds===null)return '<div aria-live="polite"></div>';const stories=filteredStories().filter(s=>{if(!term)return true;const code=selected[searchLanguage];return matchedStoryIds?.has(s.id) || false;});if(!stories.length)return `<p class="no-results">${term?'No stories match your search. Try another search or preference.':'No stories match these preferences yet. Try another selection.'}</p>`;if(term)return `<p class="search-count" role="status">${stories.length} ${stories.length===1?'story':'stories'} found</p><div class="genre-grid">${stories.map((s,i)=>card(s,i)).join('')}</div>`;return catalog.genres.filter(g=>stories.some(s=>s.genre===g)).map((g,i)=>`<section class="shelf"><div class="shelf-title"><div><h2><a href="${genreUrl(g)}">${escape(genreLabel(g))} <span aria-hidden="true">→</span></a></h2></div><span>Scroll to explore →</span></div><div class="shelf-row">${stories.filter(s=>s.genre===g).map((s,j)=>card(s,i+j,false,false)).join('')}</div></section>`).join('');}
function library(){const query=new URLSearchParams(location.search).get('q')||'';return `${header()}<main class="library"><div class="wrap"><div class="library-head"><div class="library-heading-row"><div><span class="eyebrow">STORY LIBRARY</span><h1>Browse stories</h1></div>${filters()}</div></div><div id="library-results">${libraryResults(query)}</div></div></main>${footer()}`;}

function genrePage(slug){const genre=catalog.genres.find(g=>genreSlug(g)===slug);if(!genre)return `${header()}<main class="wrap empty"><h1>Genre not found</h1><a href="/library">Back to the library →</a></main>${footer()}`;const stories=filteredStories().filter(s=>s.genre===genre);return `${header()}<main class="library"><div class="wrap"><a class="back" href="/library${filterQuery()}">← &nbsp; All genres</a><div class="library-head genre-head"><span class="eyebrow">EXPLORE BY GENRE</span><h1>${escape(genreLabel(genre))}</h1><p>Find your next story.</p>${filters()}</div>${stories.length?`<div class="genre-grid">${stories.map((s,i)=>card(s,i)).join('')}</div>`:'<p class="no-results">No stories match these preferences yet. Try another selection.</p>'}</div></main>${footer()}`;}

function renderTargetParagraph(paragraph,source){if(!paragraph.sentences)return escape(paragraph.target);const translation=paragraph.translations[source];return paragraph.sentences.map(sentence=>{const glosses=translation?.sentences?.find(item=>item.sentenceId===sentence.sentenceId)?.glosses||[];const tokens=sentence.tokens;let result='';for(let index=0;index<tokens.length;){const gloss=glosses.find(g=>g.tokenIds.length&&g.tokenIds.every((id,offset)=>tokens[index+offset]?.id===id));if(!gloss){result+=escape(tokens[index].text);index++;continue;}const text=tokens.slice(index,index+gloss.tokenIds.length).map(t=>t.text).join('');const whitespace=text.match(/^\s*/)[0],word=text.slice(whitespace.length),popupId=`gloss-${paragraph.paragraphId}-${sentence.sentenceId}-${index}`;result+=escape(whitespace)+`<span class="gloss-wrap"><button type="button" class="gloss-token" data-action="gloss" aria-expanded="false" aria-controls="${escape(popupId)}" aria-describedby="${escape(popupId)}">${escape(word)}</button><span id="${escape(popupId)}" role="tooltip" class="gloss-popup" hidden><span lang="${escape(source)}" dir="auto">${escape(gloss.translation)}</span>${gloss.romanization?`<span class="gloss-romanization">${escape(gloss.romanization)}</span>`:''}</span></span>`;index+=gloss.tokenIds.length;}return result;}).join('');}
function storyLevelUrl(level){const query=new URLSearchParams(location.search);query.set('level',level);return location.pathname+'?'+query.toString();}
function story(s){if(!s)return `${header()}<main class="wrap empty"><h1>Story not found</h1><a href="/library">Back to stories →</a></main>${footer()}`;const requested=selection().source;const source=s.sourceLanguages.includes(requested)?requested:s.sourceLanguages[0];const targetName=languageName(s.targetLanguage);const sourceName=languageName(source);const hasRomanization=s.paragraphs.some(p=>p.romanization);const next=nextStoryInSeries(s);return `${header()}<main class="reading"><a class="back" href="/library${filterQuery()}">← &nbsp; All stories</a><div class="story-cover"><img src="${escape(s.image)}" alt="Illustration for ${escape(s.title)}"></div><div class="story-heading"><span class="eyebrow">${escape(genreLabel(s.genre)).toUpperCase()} &nbsp; / &nbsp; ${escape(targetName).toUpperCase()} ${escape(s.level)}</span><h1 lang="${escape(s.targetLanguage)}" dir="auto">${escape(s.title)}</h1><p lang="${escape(s.targetLanguage)}" dir="auto">${escape(s.description)}</p></div><div class="toolbar" aria-label="Reading controls"><div class="reading-controls"><fieldset class="story-level"><legend>Level</legend><div class="story-level-options">${(s.levels||[{level:s.level}]).map(item=>`<a class="story-level-option" href="${escape(storyLevelUrl(item.level))}" ${item.level===s.level?'aria-current="page"':''}>${escape(item.level)}</a>`).join('')}</div></fieldset>${source?`<div class="translation-controls"><label class="translation-toggle"><input type="checkbox" id="show-translation" ${showTranslation?'checked':''}> Show translation</label>${showTranslation?`<label><span class="visually-hidden">Translation</span><select id="story-source">${languageOptions(s.sourceLanguages,source)}</select></label>`:''}</div>`:`<p class="translation-unavailable">${escape(translationUnavailable[interfaceLanguage]||translationUnavailable.en)}</p>`}${hasRomanization?`<button data-action="roman" aria-pressed="${roman}">${roman?'Hide Romanization':'Show Romanization'}</button>`:''}</div></div><article class="story-text">${s.paragraphs.map(p=>`<div class="paragraph">${`<p lang="${escape(s.targetLanguage)}" dir="auto">${renderTargetParagraph(p,source)}</p>${roman&&p.romanization?`<p class="pinyin">${escape(p.romanization)}</p>`:''}`}${showTranslation&&source&&p.translations[source]?.text?`<p lang="${escape(source)}" dir="auto" class="chinese">${escape(p.translations[source].text)}</p>`:''}</div>`).join('')}</article><div class="story-end"><span>✦</span><h2>Thanks for reading.</h2><p>${escape(nextChapterLabels[interfaceLanguage]||nextChapterLabels.en)}</p>${next?`<a class="button primary" href="${escape(nextStoryUrl(next))}">${escape(nextStoryLabels[interfaceLanguage]||nextStoryLabels.en)}</a>`:`<a class="button primary" href="${escape('/library'+filterQuery())}">Explore more stories →</a>`}</div></main>${footer()}`;}

