function genreLabel(genre){const index=genreNames.indexOf(genre);return genreWords[interfaceLanguage]?.[index]||genre;}
function translateInterface(){
 document.documentElement.lang=interfaceLanguage;
 const dictionary=translations[interfaceLanguage];const title='LinguaStories | A little reading goes a long way';const description='Learn a language one story at a time with LinguaStories.';document.title=interfaceLanguage==='en'?title:'LinguaStories | '+(dictionary?.['A LITTLE READING, EVERY DAY']||'A little reading goes a long way');const meta=document.querySelector('meta[name=description]');if(meta?.setAttribute)meta.setAttribute('content',dictionary?.[description]||description);if(!dictionary)return;
 const translateText=text=>{
  if(dictionary[text])return dictionary[text];
  const count=text.match(/^(\d+) (story|stories) found$/);
  if(count)return `${count[1]} ${dictionary[count[2]+' found']||count[2]+' found'}`;
  for(const key of ['All stories','All genres'])if(text.endsWith(key)&&dictionary[key])return text.slice(0,-key.length)+dictionary[key];
  return text;
 };
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 while(walker.nextNode()){
  const node=walker.currentNode;
  if(node.parentElement.closest('.card,.story-text,.story-heading,.story-cover,#preference-language,#story-source,#site-language,#site-language-link'))continue;
  const text=node.nodeValue.trim();if(text)node.nodeValue=node.nodeValue.replace(text,translateText(text));
 }
 for(const element of root.querySelectorAll('[aria-label],[title],[placeholder],[alt]')){
  for(const attr of ['aria-label','title','placeholder','alt']){
   const value=element.getAttribute(attr);if(!value)continue;
   if(element.closest('.story-text,.story-heading'))continue;
   let result=translateText(value);
   for(const prefix of ['Read','Illustration for'])if(value.startsWith(prefix+' ')&&dictionary[prefix])result=dictionary[prefix]+value.slice(prefix.length);
   element.setAttribute(attr,result);
  }
 }
}

function render(){const p=location.pathname;root.innerHTML=p==='/library'?library():p.startsWith('/library/genre/')?genrePage(p.split('/')[3]):p.startsWith('/story/')?story(currentStory):p==='/'?home():`${header()}<main class="wrap empty"><h1>Page not found</h1><a href="/">Back to home →</a></main>${footer()}`;translateInterface();}
root.addEventListener('click',e=>{const openLanguage=e.target.closest('[data-action="open-language"]');if(openLanguage){e.preventDefault();root.querySelector('#site-language')?.showModal();return;}if(e.target.closest('[data-action="open-settings"]')){e.preventDefault();root.querySelector('#reader-settings')?.showModal();return;}if(e.target.matches?.('dialog.app-modal')){if(e.target.id==='site-language')closeLanguageMenu(true);else if(e.target.id==='reader-settings')closeSettingsMenu(true);return;}const choice=e.target.closest('[data-site-language]');if(choice){const code=choice.dataset.siteLanguage;if(Object.hasOwn(siteLanguages,code)){interfaceLanguage=code;localStorage.setItem('site-language',code);render();root.querySelector('#site-language-link')?.focus();}return;}if(e.target.closest('[data-action="close-language"]')){closeLanguageMenu(true);return;}if(e.target.closest('[data-action="close-settings"]')){closeSettingsMenu(true);return;}const gloss=e.target.closest('[data-action="gloss"]');if(gloss){const popup=gloss.nextElementSibling;const open=popup.hidden;root.querySelectorAll('.gloss-token[aria-expanded="true"]').forEach(button=>{button.setAttribute('aria-expanded','false');button.nextElementSibling.hidden=true;});popup.hidden=!open;gloss.setAttribute('aria-expanded',String(open));return;}if(e.target.closest('[data-action="theme"]')){theme=theme==='dark'?'light':'dark';localStorage.setItem('site-theme',theme);document.documentElement.dataset.theme=theme;render();return;}if(e.target.closest('[data-action="roman"]')){roman=!roman;render();}const button=e.target.closest('[data-action="search"]');if(button){const input=root.querySelector('#story-search');const open=input.hidden;input.hidden=!open;button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close story search':'Open story search');button.closest('form').classList.toggle('expanded',open);translateInterface();if(open)input.focus();}});
root.addEventListener('change',e=>{if(e.target.id==='always-show-translation'){alwaysShowTranslation=e.target.checked;localStorage.setItem('reader-always-show-translation',String(alwaysShowTranslation));if(location.pathname.startsWith('/story/')){showTranslation=alwaysShowTranslation;render();const settings=root.querySelector('#reader-settings');if(settings){settings.showModal();settings.querySelector('#always-show-translation')?.focus();}}}else if(e.target.id==='show-translation'){showTranslation=e.target.checked;render()}else if(e.target.id==='story-source'){const url=new URL(location.href);url.searchParams.set('source',e.target.value);history.replaceState(null,'',url);render()}else if(e.target.id==='preference-type'){searchLanguage=e.target.value;matchedStoryIds=null;const url=new URL(location.href);url.searchParams.set('searchBy',searchLanguage);history.replaceState(null,'',url);document.querySelector('#preference-language').value=selection()[searchLanguage];render();if(location.pathname==='/library')updateSearch(new URLSearchParams(location.search).get('q')||'');}else if(e.target.id==='preference-language'){const current=selection();current[document.querySelector('#preference-type').value]=e.target.value;const query=new URLSearchParams(current);const existing=new URLSearchParams(location.search);for(const key of ['level','audio','searchBy'])if(existing.get(key))query.set(key,existing.get(key));const search=document.querySelector('#story-search')?.value.trim();if(search)query.set('q',search);location.href=location.pathname+'?'+query.toString();}else if(['level-filter','audio-filter'].includes(e.target.id)){const query=new URLSearchParams(location.search);const key=e.target.id==='level-filter'?'level':'audio';const value=key==='level'?e.target.value:(e.target.checked?'1':'');if(value)query.set(key,value);else query.delete(key);location.href=location.pathname+'?'+query.toString();}});
async function updateSearch(value){const term=value.trim(),sequence=++searchSequence;if(!term){matchedStoryIds=null;const results=document.querySelector('#library-results');if(results)results.innerHTML=libraryResults('');translateInterface();return;}matchedStoryIds=null;const query=new URLSearchParams({q:term,source:selection().source,searchBy:searchLanguage});const level=new URLSearchParams(location.search).get('level');if(level)query.set('level',level);try{const result=await api('/search?'+query.toString());if(sequence!==searchSequence)return;matchedStoryIds=new Set(result.ids);const results=document.querySelector('#library-results');if(results)results.innerHTML=libraryResults(term);translateInterface();}catch{if(sequence!==searchSequence)return;const results=document.querySelector('#library-results');if(results){results.innerHTML='<p>We couldn’t load the stories.</p>';translateInterface();}}}
root.addEventListener('input',e=>{if(e.target.id!=='story-search'||location.pathname!=='/library')return;const value=e.target.value;const url=new URL(location.href);if(value.trim())url.searchParams.set('q',value);else url.searchParams.delete('q');history.replaceState(null,'',url);updateSearch(value);});

try{catalog=await api('/catalog');if(location.pathname.startsWith('/story/')){const id=location.pathname.split('/')[2];if(catalog.stories.some(s=>s.id===id))currentStory=await api('/story/'+encodeURIComponent(id)+(new URLSearchParams(location.search).get('level')?'?level='+encodeURIComponent(new URLSearchParams(location.search).get('level')):''));}render();if(location.pathname==='/library'&&new URLSearchParams(location.search).get('q'))await updateSearch(new URLSearchParams(location.search).get('q'));}catch(e){root.innerHTML='<main class="wrap empty"><h1>We couldn’t load the stories.</h1><p>Please try again in a moment.</p></main>';translateInterface()}

function closeLanguageMenu(restoreFocus=false){const modal=root.querySelector?.('#site-language');if(modal?.open){modal.close();if(restoreFocus)root.querySelector('#site-language-link')?.focus();}}
function closeSettingsMenu(restoreFocus=false){const modal=root.querySelector?.('#reader-settings');if(modal?.open){modal.close();if(restoreFocus)root.querySelector('#reader-settings-trigger')?.focus();}}
root.addEventListener('keydown',e=>{if(e.key==='Escape'){closeLanguageMenu(true);closeSettingsMenu(true);const button=e.target.closest('[data-action="gloss"]');if(button&&button.getAttribute('aria-expanded')==='true'){button.setAttribute('aria-expanded','false');button.nextElementSibling.hidden=true;}}});
